package vn.edu.eaut.lab8.model; import java.io.Serializable; public class SinhVien implements Serializable {private int id;private String maSinhVien,hoTen,email,lop; public SinhVien(){} public SinhVien(int id,String ma,String ten,String e,String l){this.id=id;maSinhVien=ma;hoTen=ten;email=e;lop=l;} public int getId(){return id;}public void setId(int v){id=v;}public String getMaSinhVien(){return maSinhVien;}public void setMaSinhVien(String v){maSinhVien=v;}public String getHoTen(){return hoTen;}public void setHoTen(String v){hoTen=v;}public String getEmail(){return email;}public void setEmail(String v){email=v;}public String getLop(){return lop;}public void setLop(String v){lop=v;}}
